// Grid town showpiece, hand-made: a small town (real size, cm) and, smaller round it, the four stations that feed it:
// coal (west), hydel (north), wind (north-east), solar (east). One grid joins them. Through the 24-hour day the town's
// demand rises and falls (an evening peak); solar follows the sun, wind blows harder in the evening, thermal holds its
// base slowly, hydel fills the gap fast. Helpers for later parts live on W.store.
const S = W.store;
S.matte = (c, r = 0.92) => new THREE.MeshStandardMaterial({ color: c, roughness: r, metalness: 0 });
S.lamps = [];
S.lamp = (c = '#ffe2a8', k = 2.4) => { const m = W.glow(c, 0); S.lamps.push({ m, k }); return m; };
// the grid's numbers (MW): the town's demand through the day, and how the four stations share it
S.CAP = { th: 600, hy: 300, so: 250, wi: 100, thMin: 360 };
const DP = [[0, 560], [3, 520], [5, 535], [7, 640], [9, 720], [12, 770], [15, 760], [17, 745], [18, 820], [19, 930], [20, 960], [21, 920], [22, 780], [23, 640], [24, 560]];
S.demand = (h) => { h = ((h % 24) + 24) % 24; for (let i = 1; i < DP.length; i++) if (h <= DP[i][0]) { const a = DP[i - 1], b = DP[i], k = (h - a[0]) / (b[0] - a[0]); return a[1] + (b[1] - a[1]) * k * k * (3 - 2 * k); } return DP[0][1]; };
S.sunAt = (h) => Math.pow(Math.max(0, Math.min(1, Math.sin(((h - 6) / 12) * Math.PI) / 0.7)), 0.9); // (panels: low sun, little power)
S.windAt = (h) => 0.45 + 0.3 * Math.sin(((h - 14) / 24) * Math.PI * 2);
S.plan = (h, scale, clouds) => { // the planned share at an hour (the big screen's chart)
  const D = S.demand(h) * scale, so = S.CAP.so * S.sunAt(h) * (clouds ? 0.35 : 1), wi = S.CAP.wi * S.windAt(h);
  const th = Math.max(S.CAP.thMin, Math.min(S.CAP.th, D - so - wi - 140));
  const hy = Math.max(0, Math.min(S.CAP.hy, D - th - so - wi));
  return { D, th, so, wi, hy, short: Math.max(0, D - th - so - wi - hy) };
};
W.day({ start: 18.5, ground: '#6c7d4e', zoom: 0.5 });
const land = W.group();
land.add(W.mesh(W.box(60000, 10, 50000), S.matte('#6f8150', 0.98), { at: [0, -6, -8000] }));
land.add(W.mesh(W.box(19000, 8, 15000), S.matte('#a59f92', 0.95), { at: [0, -1, 0] })); // the town's ground
const road = S.matte('#4f5357', 0.9);
for (const z of [-4500, 0, 4500]) land.add(W.mesh(W.box(19000, 6, 700), road, { at: [0, 4, z] }));
for (const x of [-6000, 0, 6000]) land.add(W.mesh(W.box(700, 6, 15000), road, { at: [x, 4, 0] }));
land.add(W.mesh(W.box(700, 6, 14000), road, { at: [0, 4, -14000] }));
const marks = new THREE.InstancedMesh(new THREE.BoxGeometry(300, 2, 30), S.matte('#e8e6dc', 0.6), 40);
for (let i = 0; i < 40; i++) marks.setMatrixAt(i, new THREE.Matrix4().makeTranslation(-9000 + i * 470, 8, 0));
land.add(marks);
W.add(land, { label: 'ఊరు', ground: true });

const S = W.store;
// four colonies (each its own lights, so one can go dark when the grid is short), flats, a school, a hospital, a tank
const winTex = W.canvasTex(128, 128), winGlow = W.canvasTex(128, 128);
{
  const g = winTex.ctx, e = winGlow.ctx;
  g.fillStyle = '#efe7d6'; g.fillRect(0, 0, 128, 128); e.fillStyle = '#000'; e.fillRect(0, 0, 128, 128);
  for (const [x, y] of [[18, 30], [74, 30], [18, 80], [74, 80]]) { g.fillStyle = '#3c5266'; g.fillRect(x, y, 34, 26); e.fillStyle = '#ffd38a'; e.fillRect(x, y, 34, 26); }
  g.fillStyle = '#7a5a3a'; g.fillRect(52, 92, 22, 36);
  winTex.update(); winGlow.update();
}
S.colonies = [];
const house = new THREE.BoxGeometry(900, 600, 800), roof = new THREE.ConeGeometry(720, 300, 4);
roof.rotateY(Math.PI / 4);
const QUAD = [[-1, -1], [1, -1], [-1, 1], [1, 1]];
const COLS = ['#efe7d6', '#e8dcc6', '#f2ece0', '#e4e8ea', '#f0dfd0'];
const RC = ['#a8432f', '#8c3b2c', '#6f6a64', '#b5562f'];
const homes = W.group(), flats = W.group(), lights = W.group();
const pole = W.metal('#8d939a', { rough: 0.5 });
QUAD.forEach(([qx, qz], ci) => {
  const wm = new THREE.MeshStandardMaterial({ map: winTex.texture, emissiveMap: winGlow.texture, emissive: new THREE.Color('#ffc977'), emissiveIntensity: 0, roughness: 0.75 });
  const n = 12, hm = new THREE.InstancedMesh(house, wm, n), rm = new THREE.InstancedMesh(roof, S.matte('#a8432f', 0.8), n);
  const c = new THREE.Color(), M = new THREE.Matrix4();
  for (let i = 0; i < n; i++) {
    const r = Math.floor(i / 4), k = i % 4;
    const x = qx * (1300 + k * 1150), z = qz * (900 + r * 1150) + (qz < 0 ? -0 : 0);
    hm.setMatrixAt(i, M.makeTranslation(x, 300, z)); rm.setMatrixAt(i, M.makeTranslation(x, 750, z));
    hm.setColorAt(i, c.set(COLS[(i + ci) % COLS.length])); rm.setColorAt(i, c.set(RC[(i * 3 + ci) % RC.length]));
  }
  homes.add(hm, rm);
  const fm = new THREE.MeshStandardMaterial({ map: winTex.texture, emissiveMap: winGlow.texture, emissive: new THREE.Color('#ffc977'), emissiveIntensity: 0, roughness: 0.75 });
  winTex.texture.wrapS = winTex.texture.wrapT = THREE.RepeatWrapping;
  const fl = W.mesh(W.box(1400, 1600, 1000), fm, { at: [qx * 7600, 800, qz * 2300] });
  flats.add(fl);
  flats.add(W.mesh(W.box(1440, 60, 1040), S.matte('#9aa1a8'), { at: [qx * 7600, 1630, qz * 2300] }));
  const lm = S.lamp('#ffe7b0', 3);
  for (let i = 0; i < 4; i++) {
    const x = qx * (1100 + i * 1300), z = qz * 450;
    lights.add(W.mesh(W.cyl(8, 10, 700, 6), pole, { at: [x, 350, z] }), W.mesh(W.box(80, 10, 30), lm, { at: [x, 695, z - qz * 30] }));
  }
  S.colonies.push({ wm, fm, lm, shed: false });
});
W.add(homes, { label: 'ఇళ్ళు', heat: [26, 34] });
W.add(flats, { label: 'అపార్ట్‌మెంట్లు', heat: [26, 34] });
W.add(lights, { label: 'వీధి దీపాలు' });
const pub = W.group();
pub.add(W.mesh(W.box(2600, 700, 1100), S.matte('#e9d79a', 0.8), { at: [-6000, 350, -6300] }));
pub.add(W.text('పాఠశాల', { size: 160, at: [-6000, 520, -5745], color: '#2f5f8a' }));
pub.add(W.mesh(W.box(2200, 1000, 1200), S.matte('#f3f4f2', 0.7), { at: [6000, 500, -6300] }));
pub.add(W.text('ఆసుపత్రి', { size: 170, at: [6000, 760, -5695], color: '#2e8a5a' }));
S.hospM = S.lamp('#e9fff4', 1.4); S.lamps[S.lamps.length - 1].always = 0.5; S.lamps[S.lamps.length - 1].hosp = true;
pub.add(W.mesh(W.box(2000, 60, 30), S.hospM, { at: [6000, 300, -5690] }));
pub.add(W.mesh(W.cyl(500, 500, 600, 24), S.matte('#d9d4c8', 0.85), { at: [1800, 1700, 6200] }), W.mesh(W.cyl(90, 120, 1400, 12), S.matte('#d9d4c8', 0.85), { at: [1800, 700, 6200] }));
W.add(pub, { label: 'స్కూల్, ఆసుపత్రి', heat: [26, 32] });

const S = W.store;
const gal = W.metal('#aab2ba', { rough: 0.45 }), tank = W.paint('#5f6b5e', { metallic: 0.35, rough: 0.55 }), porc = S.matte('#7a4a32', 0.4);
const sub = (x, z, big) => {
  const g = W.group({ at: [x, 0, z] });
  g.add(W.mesh(W.box(big ? 3600 : 2000, 10, big ? 2600 : 1500), S.matte('#8b867d', 0.98), { at: [0, 5, 0] }));
  for (const dx of big ? [-900, 900] : [0]) {
    g.add(W.mesh(W.box(600, 450, 420), tank, { at: [dx, 235, 0] }));
    for (let k = 0; k < 3; k++) g.add(W.mesh(W.cyl(18, 26, 200, 10), porc, { at: [dx - 150 + k * 150, 560, 0] }));
  }
  for (const dx of [-1, 1]) { g.add(W.mesh(W.box(50, 1300, 50), gal, { at: [dx * (big ? 1600 : 900), 650, -900] })); }
  g.add(W.mesh(W.box(big ? 3250 : 1850, 50, 50), gal, { at: [0, 1300, -900] }));
  return g;
};
const gs = W.group();
gs.add(sub(0, -11500, true));
gs.add(W.text('220 kV గ్రిడ్ సబ్‌స్టేషన్', { size: 120, at: [0, 300, -10180], color: '#eef2f5', bg: '#2f5f8a' }));
W.add(gs, { label: 'గ్రిడ్ సబ్‌స్టేషన్', heat: [28, 66] });
const ts = W.group();
ts.add(sub(-2200, -8200, false));
for (const [x, z] of [[-6000, -6800], [6000, -6800], [-8800, 900], [8800, 900]]) ts.add(W.mesh(W.tube([[-2200, 800, -8200], [(x - 2200) / 2, 650, (z - 8200) / 2], [x, 700, z]], 6, 16), W.metal('#6c7076')));
for (let x = -9000; x <= 9000; x += 3000) ts.add(W.mesh(W.cyl(10, 14, 800, 6), S.matte('#9a958a'), { at: [x, 400, -2200] }));
ts.add(W.mesh(W.tube([[-9000, 760, -2200], [0, 700, -2200], [9000, 760, -2200]], 5, 24), W.metal('#6c7076')));
W.add(ts, { label: 'ఊరి సబ్‌స్టేషన్', heat: [28, 60] });
const lines = W.group();
S.ends = { th: [-21000, 3200, -6000], hy: [-6000, 3200, -22000], wi: [14000, 3200, -21000], so: [21000, 3200, -4000], gs: [0, 1400, -12500] };
const tower = (x, z) => {
  const t = W.group({ at: [x, 0, z] });
  for (const [dx, dz] of [[-1, -1], [-1, 1], [1, -1], [1, 1]]) {
    const A = new THREE.Vector3(dx * 200, 0, dz * 200), B = new THREE.Vector3(dx * 40, 3000, dz * 40);
    const m = new THREE.Mesh(new THREE.CylinderGeometry(12, 12, A.distanceTo(B), 4), gal);
    m.position.copy(A).add(B).multiplyScalar(0.5); m.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), B.clone().sub(A).normalize());
    t.add(m);
  }
  t.add(W.mesh(W.box(1100, 36, 36), gal, { at: [0, 2900, 0], rot: [0, Math.atan2(z, x) * 57.3, 0] }));
  return t;
};
for (const k of ['th', 'hy', 'wi', 'so']) {
  const a = S.ends[k], b = S.ends.gs, mid = [(a[0] + b[0]) / 2, 0, (a[2] + b[2]) / 2];
  lines.add(tower(mid[0], mid[2]));
  lines.add(W.mesh(W.tube([a, [(a[0] + mid[0]) / 2, 2400, (a[2] + mid[2]) / 2], [mid[0], 2950, mid[2]], [(b[0] + mid[0]) / 2, 2200, (b[2] + mid[2]) / 2], b], 9, 40), W.metal('#6c7076')));
}
lines.add(W.mesh(W.tube([[0, 1300, -12400], [-1100, 1000, -10000], [-2200, 1300, -9100]], 9, 20), W.metal('#6c7076')));
W.add(lines, { label: 'ట్రాన్స్‌మిషన్ లైన్లు', heat: [28, 52] });

const S = W.store;
// the four stations, smaller than life so they fit round the town
const white = W.paint('#f1f3f4', { metallic: 0.15, rough: 0.35 }), conc = S.matte('#c9c3b8', 0.88);
const th = W.group({ at: [-23500, 0, -6000] });
const rAt = (y) => 1300 * Math.sqrt(1 + Math.pow((y - 3900) / 2760, 2));
const prof = []; for (let y = 400; y <= 5200; y += 400) prof.push([rAt(y), y]);
th.add(W.mesh(W.lathe(prof, 40), new THREE.MeshStandardMaterial({ color: '#d2ccc0', roughness: 0.92, side: THREE.DoubleSide }), { at: [2400, 0, -1600] }));
th.add(W.mesh(W.cyl(rAt(400) + 100, rAt(400) + 100, 400, 40), conc, { at: [2400, 200, -1600] }));
th.add(W.mesh(W.box(2000, 3000, 2000), W.paint('#c4ccd4'), { at: [-1500, 1500, 0] }), W.mesh(W.box(3600, 1400, 1500), W.paint('#d3d6d9'), { at: [1000, 700, 1200] }));
th.add(W.mesh(W.cyl(250, 420, 7000, 24), conc, { at: [-1500, 3500, -2600] }));
th.add(W.mesh(W.box(2600, 500, 2600), S.matte('#202022'), { at: [-4200, 250, 1500] }));
S.thG = th;
W.add(th, { label: 'థర్మల్ కేంద్రం', heat: [32, 140] });
const hy = W.group({ at: [-6000, 0, -26000] });
const hill = W.lathe([[5400, 0], [4600, 900], [3600, 2300], [2500, 3500], [1400, 4400], [600, 4850], [0.01, 5000]], 32);
hy.add(W.mesh(hill, S.matte('#76804f'), { at: [-5600, 0, -1000] }), W.mesh(hill, S.matte('#76804f'), { at: [5600, 0, -1000], rot: [0, 40, 0] }));
hy.add(W.mesh(W.box(6600, 3200, 900), conc, { at: [0, 1600, 0] }));
hy.add(W.mesh(new THREE.PlaneGeometry(16000, 7000), new THREE.MeshStandardMaterial({ color: '#2d6d93', roughness: 0.1, metalness: 0.15 }), { at: [0, 2900, -4000], rot: [-90, 0, 0] }));
hy.add(W.mesh(W.box(2600, 900, 1100), W.paint('#e6e1d6'), { at: [-1600, 450, 1500] }));
for (const x of [-2400, -1600, -800]) hy.add(W.mesh(W.tube([[x, 2600, -100], [x, 1200, 600], [x, 400, 1000]], 140, 16), W.paint('#5b6670')));
hy.add(W.mesh(new THREE.PlaneGeometry(3000, 6000), new THREE.MeshStandardMaterial({ color: '#3a7c9e', roughness: 0.18 }), { at: [0, 30, 4000], rot: [-90, 0, 0] }));
W.add(hy, { label: 'హైడల్ కేంద్రం', heat: [24, 60] });
const wf = W.group();
S.wRotors = [];
for (const [x, z] of [[11500, -22500], [14500, -25500], [17500, -21000]]) {
  const t = W.group({ at: [x, 0, z] });
  t.add(W.mesh(W.cyl(70, 120, 5000, 16), white, { at: [0, 2500, 0] }));
  t.add(W.mesh(W.box(220, 220, 700, 30), white, { at: [0, 5100, -150] }));
  const r = W.group({ at: [0, 5100, 280] });
  r.add(W.mesh(W.sphere(110, 12), white));
  for (let i = 0; i < 3; i++) { const a = W.group({ rot: [0, 0, i * 120] }); a.add(W.mesh(W.box(140, 3000, 30), white, { at: [0, 1550, 0] })); r.add(a); }
  t.add(r);
  wf.add(t);
  S.wRotors.push(r);
}
W.add(wf, { label: 'గాలి మరలు', heat: [26, 30] });
const so = W.group({ at: [23500, 0, -4000] });
const cell = W.paint('#1d3d7a', { metallic: 0.1, rough: 0.35 });
S.soRows = [];
for (let i = 0; i < 10; i++) {
  const row = W.group({ at: [-3000 + i * 650, 220, 0] });
  row.add(W.mesh(W.box(460, 8, 7000), cell));
  so.add(row, W.mesh(W.box(14, 220, 14), W.metal('#9aa2aa'), { at: [-3000 + i * 650, 110, 0] }));
  S.soRows.push(row);
}
so.add(W.mesh(W.box(800, 260, 250), W.paint('#eef1f3'), { at: [3800, 130, 2500] }));
W.add(so, { label: 'సోలార్ ఫారం', heat: [28, 60] });

const S = W.store;
// the load dispatch screen in the town square: the day's demand (white line), how each station shares it (coloured
// layers: thermal, wind, solar, hydel), a line for now, the frequency
S.scr = W.canvasTex(1024, 512);
const sm = new THREE.MeshStandardMaterial({ color: 0x000000, emissive: 0xffffff, emissiveMap: S.scr.texture, emissiveIntensity: 1, map: S.scr.texture });
const scr = W.group({ at: [3200, 0, 9200] });
scr.add(W.mesh(new THREE.PlaneGeometry(2800, 1400), sm, { at: [0, 1500, 0] }));
scr.add(W.mesh(W.box(2900, 1500, 60), W.paint('#2a2e33'), { at: [0, 1500, -40] }));
for (const x of [-1100, 1100]) scr.add(W.mesh(W.box(100, 800, 100), W.paint('#2a2e33'), { at: [x, 400, -40] }));
W.add(scr, { label: 'లోడ్ డిస్పాచ్ స్క్రీన్' });

const S = W.store;
// running (every frame): demand from the hour × the power bar (🏙️ how much the town uses: winter 70% … summer 100%; past
// the limit a heat wave). Solar from the sun (🚩 "clouds" cut it), wind stronger in the evening, thermal slow and steady,
// hydel quick, filling the rest. Short of power → the frequency falls → one colony at a time is switched off (load
// shedding) so the rest of the grid stays safe. 🎮 game "grid": hydel is his (the power bar), the frequency is his job.
const cr = W.group({ at: [-3200, 0, 9200] });
cr.add(W.mesh(W.box(1600, 600, 1000), S.matte('#e4e1d9', 0.8), { at: [0, 300, 0] }));
cr.add(W.mesh(W.box(1200, 140, 20), S.lamp('#bfe6ff', 1.2), { at: [0, 380, 510] }));
S.lamps[S.lamps.length - 1].always = 0.6;
cr.add(W.text('గ్రిడ్ కంట్రోల్', { size: 90, at: [0, 520, 512], color: '#2f5f8a' }));
W.add(cr, { label: 'గ్రిడ్ కంట్రోల్ రూమ్', heat: [24, 26] });
W.throttle({ label: 'వాడకం', rise: 0.6, fall: 0.6, start: 1 });
W.sound({ kind: 'hum', label: 'గ్రిడ్ సబ్‌స్టేషన్', gain: 0.5, f0: 100 });
const town = W.sound({ kind: 'plant', label: 'ఊరు', gain: 0.35 });
const puffG = new THREE.SphereGeometry(1, 10, 8), puffs = [];
for (let i = 0; i < 14; i++) {
  const m = new THREE.Mesh(puffG, new THREE.MeshStandardMaterial({ color: '#ffffff', roughness: 1, transparent: true, opacity: 0, depthWrite: false }));
  m.userData.isEdge = true; m.raycast = () => {}; m.castShadow = false;
  S.thG.add(m);
  puffs.push({ m, age: (i / 14) * 10, s: (i * 0.618) % 1 });
}
const live = { th: 520, hy: 150, so: 0, wi: 50, f: 50, shed: 0, shedT: 0, okT: 0 };
let hudT = 0, scrT = -9, wang = 0, lastH = W.env.hour;
const CC = { th: '#9aa0a8', wi: '#7fd0ff', so: '#ffc23a', hy: '#3a8cff' };
const draw = (h, scale, clouds) => {
  const g = S.scr.ctx, W0 = 1024, H0 = 512, x0 = 70, x1 = 1000, y0 = 440, y1 = 90, top = 1150;
  g.fillStyle = '#04101a'; g.fillRect(0, 0, W0, H0);
  g.fillStyle = '#8fe7ff'; g.font = '700 34px system-ui, "Noto Sans Telugu", sans-serif';
  g.fillText('ఊరి కరెంట్ · 24 గంటలు', 24, 50);
  g.textAlign = 'right'; g.fillStyle = Math.abs(live.f - 50) < 0.1 ? '#9fe6a0' : live.f < 49.8 ? '#ff7a6a' : '#ffd36a';
  g.fillText(live.f.toFixed(2) + ' Hz', 1000, 50); g.textAlign = 'left';
  const X = (hh) => x0 + (x1 - x0) * hh / 24, Y = (mw) => y0 - (y0 - y1) * mw / top;
  const keys = ['th', 'wi', 'so', 'hy'];
  const pts = []; for (let i = 0; i <= 96; i++) { const hh = i / 4; pts.push([hh, S.plan(hh, scale, clouds)]); }
  let base = pts.map(() => 0);
  for (const k of keys) {
    g.beginPath();
    pts.forEach(([hh, p], i) => { const y = Y(base[i] + p[k]); if (i === 0) g.moveTo(X(hh), y); else g.lineTo(X(hh), y); });
    for (let i = pts.length - 1; i >= 0; i--) g.lineTo(X(pts[i][0]), Y(base[i]));
    g.closePath(); g.fillStyle = CC[k]; g.globalAlpha = 0.85; g.fill(); g.globalAlpha = 1;
    base = base.map((b, i) => b + pts[i][1][k]);
  }
  g.strokeStyle = '#ffffff'; g.lineWidth = 4; g.beginPath();
  pts.forEach(([hh, p], i) => { const y = Y(p.D); if (i === 0) g.moveTo(X(hh), y); else g.lineTo(X(hh), y); }); g.stroke();
  g.strokeStyle = '#ff5a8a'; g.lineWidth = 3; g.beginPath(); g.moveTo(X(h), y1 - 10); g.lineTo(X(h), y0); g.stroke();
  g.fillStyle = '#c9d4dc'; g.font = '500 22px system-ui, sans-serif';
  for (const hh of [0, 6, 12, 18, 24]) g.fillText(String(hh), X(hh) - 10, 475);
  g.font = '600 24px system-ui, "Noto Sans Telugu", sans-serif';
  [['థర్మల్', 'th'], ['గాలి', 'wi'], ['సోలార్', 'so'], ['హైడల్', 'hy']].forEach(([n, k], i) => { g.fillStyle = CC[k]; g.fillRect(70 + i * 230, 488, 22, 18); g.fillStyle = '#e8f4ff'; g.fillText(n + ' ' + Math.round(live[k]), 100 + i * 230, 505); });
  S.scr.update();
};
W.onTick((t, dt) => {
